#include "cpuSw_btDriver_btDriver.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void cpuSw_btDriver_btDriver_initialize(void);
void cpuSw_btDriver_btDriver_notify(microkit_channel channel);
void cpuSw_btDriver_btDriver_timeTriggered(void);

volatile sb_queue_Common_DummyMessage_Impl_1_t *btRecv_queue_1;
sb_queue_Common_DummyMessage_Impl_1_Recv_t btRecv_recv_queue;
volatile sb_queue_Common_DummyMessage_Impl_1_t *btSend_queue_1;

#define PORT_FROM_MON 0

bool btRecv_is_empty(void) {
  return sb_queue_Common_DummyMessage_Impl_1_is_empty(&btRecv_recv_queue);
}

bool get_btRecv_poll(sb_event_counter_t *numDropped, Common_DummyMessage_Impl *data) {
  return sb_queue_Common_DummyMessage_Impl_1_dequeue((sb_queue_Common_DummyMessage_Impl_1_Recv_t *) &btRecv_recv_queue, numDropped, data);
}

bool get_btRecv(Common_DummyMessage_Impl *data) {
  sb_event_counter_t numDropped;
  return get_btRecv_poll (&numDropped, data);
}

uintmax_t get_btRecv_num_invalid(void) {
  return sb_queue_Common_DummyMessage_Impl_1_numInvalid((sb_queue_Common_DummyMessage_Impl_1_Recv_t *) &btRecv_recv_queue);
}

bool put_btSend(const Common_DummyMessage_Impl *data) {
  sb_queue_Common_DummyMessage_Impl_1_enqueue((sb_queue_Common_DummyMessage_Impl_1_t *) btSend_queue_1, (Common_DummyMessage_Impl *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_Common_DummyMessage_Impl_1_Recv_init(&btRecv_recv_queue, (sb_queue_Common_DummyMessage_Impl_1_t *) btRecv_queue_1);

  sb_queue_Common_DummyMessage_Impl_1_init((sb_queue_Common_DummyMessage_Impl_1_t *) btSend_queue_1);

  cpuSw_btDriver_btDriver_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      cpuSw_btDriver_btDriver_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      cpuSw_btDriver_btDriver_notify(channel);
  }
}
